using System.Diagnostics;
using System.Text.Json;
using RAWSelectionAssistant.Core.Services.Projects;
using RAWSelectionAssistant.Core.Services.Color;
namespace RAWSelectionAssistant.Tests;
[TestClass] public sealed class R53HomeSceneExposureTests
{
 public static ProfessionalRawMaster Master(int w=2400,int h=1600){var m=R53ProfessionalLocalTests.Master(w,h);var a=m.Image.Rgb32.ToArray();for(int y=0;y<h;y++)for(int x=0;x<w;x++){int i=(y*w+x)*3;float v=.005f+2f*x/w; a[i]=v; a[i+1]=v*(.7f+.2f*y/h); a[i+2]=v*.6f;}return m with{Image=new(w,h,a,"16",ProfessionalRawPipeline.WorkingSpace)};}
 [TestMethod]public void SceneDragBaselineColdBasesAreNotHotLocalTimings(){var dir=Environment.GetEnvironmentVariable("KITAO_HOME_SCENE_BASELINE");if(dir is null){Assert.Inconclusive("Baseline is explicit home-only measurement");return;}using var image=Master().Image;var m=Master(24,16) with{Image=image};var times=new List<double>();long allocated=GC.GetTotalAllocatedBytes(true);foreach(double ev in new[]{-.5,-1d,-1.5}){var d=new ProfessionalRawDefinition{SceneExposure=new(ev)};var timer=Stopwatch.StartNew();using var b=ProfessionalRawLocalRenderer.FastBase(m,d,400);using var result=ProfessionalRawLocalRenderer.Fast(m,d,b);times.Add(timer.Elapsed.TotalMilliseconds);}Directory.CreateDirectory(dir);File.WriteAllText(Path.Combine(dir,"SCENE_EV_BASELINE.json"),JsonSerializer.Serialize(new{width=image.Width,height=image.Height,edge=400,times,allocated=GC.GetTotalAllocatedBytes(true)-allocated,peak=Process.GetCurrentProcess().PeakWorkingSet64,source="Explicit synthetic smooth HDR, same home machine; not company timing or mouse acceptance"},new JsonSerializerOptions{WriteIndented=true}));}

 [TestMethod]public void ScenePreparedPreviewHasBoundedErrorAndHotCost(){var m=Master();var d=new ProfessionalRawDefinition{SceneExposure=new(-1)};var timer=Stopwatch.StartNew();using var samples=SceneExposureInteractiveV1.Prepare(m,d,400);double cold=timer.Elapsed.TotalMilliseconds;var times=new List<double>();double mean=0,p95=0,max=0;foreach(double ev in new[]{-.5,-1d,-1.5}){timer.Restart();using var result=SceneExposureInteractiveV1.Render(m,d with{SceneExposure=new(ev)},samples,400);times.Add(timer.Elapsed.TotalMilliseconds);using var fine=ProfessionalRawLocalRenderer.Preview(m,d with{SceneExposure=new(ev)},400);var errors=result.Rgb32.ToArray().Zip(fine.Rgb32.ToArray(),(a,b)=>Math.Abs(a-b)*255).Order().ToArray();mean=Math.Max(mean,errors.Average());p95=Math.Max(p95,errors[(int)(errors.Length*.95)]);max=Math.Max(max,errors[^1]);}Assert.IsTrue(mean<=1.5&&p95<=4&&max<=32,$"mean {mean} p95 {p95} max {max}");var dir=Environment.GetEnvironmentVariable("KITAO_HOME_SCENE_EVIDENCE");if(dir is not null){Directory.CreateDirectory(dir);File.WriteAllText(Path.Combine(dir,"SCENE_EV_HOT.json"),JsonSerializer.Serialize(new{width=m.Image.Width,height=m.Image.Height,edge=400,cold,times,mean,p95,max,samplesBytes=samples.Rgb32.Length*4,notPixelEqual=true,scope="Same home synthetic smooth HDR/size/EV values as baseline; not absolute color accuracy or mouse test"},new JsonSerializerOptions{WriteIndented=true}));}m.Image.Dispose();}
 [TestMethod]public void CacheClearDoesNotDisposeInFlightBorrowAndAccountingReturns(){long before=StudioGlobalResources.AccountedBytes;var cache=new LeasedPreviewBufferCache(1);var buffer=new HighBitDepthImageBuffer(20,10,new float[600]);using(var lease=cache.StoreAndAcquire("a",buffer)){Assert.AreEqual(before+2400,StudioGlobalResources.AccountedBytes);cache.Clear();Assert.AreEqual(600,lease.Buffer.Rgb32.Length);Assert.AreEqual(before+2400,StudioGlobalResources.AccountedBytes);}Assert.AreEqual(before,StudioGlobalResources.AccountedBytes);Assert.ThrowsExactly<ObjectDisposedException>(()=>_ = buffer.Rgb32);for(int i=0;i<100;i++){using var lease=cache.StoreAndAcquire(i.ToString(),new(20,10,new float[600]));}cache.Dispose();Assert.AreEqual(before,StudioGlobalResources.AccountedBytes);}
 [TestMethod]public void ScenePreparedCancellationAndHistoricalDefinitionRemainStable(){var m=Master(60,40);var legacy=new ProfessionalRawDefinition();using var before=ProfessionalRawPipeline.Render(m,legacy);using var cts=new CancellationTokenSource();cts.Cancel();Assert.ThrowsExactly<OperationCanceledException>(()=>SceneExposureInteractiveV1.Prepare(m,new(){SceneExposure=new(1)},400,cts.Token));using var after=ProfessionalRawPipeline.Render(m,legacy);CollectionAssert.AreEqual(before.Rgb32.ToArray(),after.Rgb32.ToArray());Assert.IsFalse(JsonSerializer.Serialize(legacy).Contains("SceneExposure"));m.Image.Dispose();}
 [TestMethod]public void GeometryV2ExportsPixelCentersForIndependentReferenceComparison(){var dir=Environment.GetEnvironmentVariable("KITAO_HOME_SCENE_EVIDENCE");if(dir is null){Assert.Inconclusive("Explicit numerical reference output");return;}var m=Master(47,31);var d=new ProfessionalRawDefinition{Geometry=new ProfessionalRawGeometry(.08,.1,.8,.75,1,true,2){StraightenDegrees=3}};using var basis=ProfessionalRawLocalRenderer.Region(m,new(),0,0,47,31);using var actual=ProfessionalRawPipeline.Render(m,d);var coordinates=Enumerable.Range(0,actual.Width*actual.Height).Select(i=>{var p=d.Geometry.SourceTuple((i%actual.Width+.5)/actual.Width,(i/actual.Width+.5)/actual.Height,47d/31);return new[]{p.X*47-.5,p.Y*31-.5};}).ToArray();Directory.CreateDirectory(dir);File.WriteAllText(Path.Combine(dir,"GEOMETRY_REFERENCE_INPUT.json"),JsonSerializer.Serialize(new{width=47,height=31,outputWidth=actual.Width,outputHeight=actual.Height,input=basis.Rgb32.ToArray(),actual=actual.Rgb32.ToArray(),coordinates,definition=d.Geometry}));m.Image.Dispose();}
 [TestMethod]public void RetiredCacheGenerationCannotReinsertLateTaskAndOldRenderedDefaultsStay(){var cache=new LeasedPreviewBufferCache();long epoch=cache.Generation;cache.Clear();var late=new HighBitDepthImageBuffer(2,2,new float[12]);Assert.ThrowsExactly<OperationCanceledException>(()=>cache.StoreAndAcquire("late",late,epoch));Assert.ThrowsExactly<ObjectDisposedException>(()=>_ = late.Rgb32);cache.Dispose();var d=new ProfessionalRawDefinition(5,"Rendered",InputConfiguration:"RenderedSrgbFloatV1",DisplayTransform:"RenderedSrgbIdentityV1");Assert.IsFalse(JsonSerializer.Serialize(d).Contains("Geometry"));Assert.IsFalse(JsonSerializer.Serialize(d).Contains("SceneExposure"));d.Validate();Assert.ThrowsExactly<NotSupportedException>(()=>(d with{Geometry=new()}).Validate());Assert.ThrowsExactly<InvalidDataException>(()=>new ProfessionalRawGeometry{StraightenDegrees=1}.Validate());}
 [TestMethod]public void SceneHighFrequencyApproximationRecordsItsActualGate(){var dir=Environment.GetEnvironmentVariable("KITAO_HOME_SCENE_EVIDENCE");if(dir is null){Assert.Inconclusive("Explicit scene approximation output");return;}var m=R53ProfessionalLocalTests.Master(2400,1600);var d=new ProfessionalRawDefinition{SceneExposure=new(-1)};using var samples=SceneExposureInteractiveV1.Prepare(m,d,800);using var quick=SceneExposureInteractiveV1.Render(m,d,samples,800);using var fine=ProfessionalRawLocalRenderer.Preview(m,d,800);var e=quick.Rgb32.ToArray().Zip(fine.Rgb32.ToArray(),(a,b)=>Math.Abs(a-b)*255).Order().ToArray();double mean=e.Average(),p95=e[(int)(e.Length*.95)],max=e[^1];File.WriteAllText(Path.Combine(dir,"SCENE_HIGH_FREQUENCY_GATE.json"),JsonSerializer.Serialize(new{mean,p95,max,withinFixedBudget=mean<=1.5&&p95<=4&&max<=32,mode=samples.SourceBitDepth,scope="Adversarial 29-period RGB source; not the smooth HDR or Canon sample; retain failures"},new JsonSerializerOptions{WriteIndented=true}));Assert.IsTrue(mean<=1.5&&p95<=4&&max<=32);m.Image.Dispose();}
}
